# slug, title, module, minutes, summary, objectives, prerequisites, explanation, terms, example, exercise, misconceptions, mastery, facts
_ROWS = [
('pf-variables','Variables and Values','pf-core',25,'Use named storage to represent information that changes as a program runs.', ['Distinguish a name from the value it refers to.','Choose clear names and update bindings safely.'], [], 'A variable is a name bound to a value. Assignment evaluates the right-hand side first, then binds the name; it is not a mathematical equation that remains true forever. Names make state explicit and let later statements reuse computed information. Prefer descriptive names and update them only when the model of the problem changes.', [('binding','Assignment binds a name to the value of its right-hand expression.'),('reuse','A later statement can read the current value associated with a name.'),('update','Reassignment replaces the name’s current binding; earlier values are not retroactively changed.'),('naming','A descriptive name communicates the role of a value to a reader.')]),
('pf-conditionals','Boolean Logic and Conditionals','pf-core',30,'Use true/false expressions to choose which instructions run.', ['Evaluate Boolean conditions.','Choose if/else branches for mutually exclusive cases.'], ['pf-variables'], 'A conditional evaluates a Boolean expression and selects a branch. The condition is checked when execution reaches it; only the chosen branch runs. Put the most specific cases first when using an if/elif/else chain, and make the final fallback intentional. Combining comparisons with and/or/not allows a rule to express more than one requirement.', [('boolean','A Boolean value has exactly two states: true or false.'),('branch','An if/else construct selects a path based on a condition at run time.'),('elif','An elif branch is considered only if all earlier conditions were false.'),('and-or','A compound condition can require both predicates or accept either predicate.')]),
('pf-loops','Loops and Iteration','pf-core',35,'Repeat work over a sequence or while a condition remains true.', ['Trace loop state across iterations.','Select a bounded for-loop or condition-controlled while-loop.'], ['pf-conditionals'], 'A loop repeats a body. A for-loop is suited to processing each item in an iterable; a while-loop repeats while its condition remains true. For a while-loop, identify the state that changes and prove it eventually reaches a stopping condition. Off-by-one errors often come from confusing a count with the last valid index.', [('iteration','One execution of a loop body is an iteration.'),('for-loop','A for-loop visits items from an iterable in sequence.'),('while-loop','A while-loop checks its condition before each iteration.'),('termination','A loop terminates when its iteration source is exhausted or its condition becomes false.')]),
('py-values','Python Values, Types, and Expressions','py-core',30,'Understand Python objects, basic types, operators, and expression evaluation.', ['Identify common built-in types.','Predict the result of arithmetic and comparison expressions.'], [], 'Python expressions evaluate to objects. Types determine which operations are meaningful and how values behave. Integers and floats represent numbers; strings represent text; Booleans represent truth values. Operators follow precedence rules, so parentheses are useful when they make intent clearer. Assignment binds a name to an object rather than declaring a fixed mathematical variable.', [('int-float','int represents whole-number values while float represents binary floating-point values.'),('string','A str is an immutable sequence of Unicode text.'),('bool','bool has the values True and False and is used by conditions.'),('precedence','Parentheses can make expression grouping explicit and override normal operator precedence.')]),
('py-strings','Strings and Formatting','py-core',30,'Create, inspect, and format immutable text values.', ['Use indexing and slicing without mutating strings.','Choose interpolation that keeps output readable.'], ['py-values'], 'Python strings are immutable sequences of Unicode code points. Indexing reads one position and slicing creates a substring; negative indexes count from the end, and slice stop positions are excluded. For readable output that mixes text and values, f-strings evaluate expressions inside braces. When text comes from untrusted users, formatting is not a substitute for context-appropriate escaping.', [('immutable','A string operation produces a new string instead of changing characters in place.'),('slice','The stop index in s[start:stop] is excluded from the result.'),('negative-index','Index -1 refers to the final character of a nonempty string.'),('f-string','An f-string evaluates expressions inside braces when the string is created.')]),
('py-functions','Functions, Parameters, and Return Values','py-core',40,'Package reusable behavior behind named inputs and explicit outputs.', ['Distinguish parameters from arguments.','Return values for callers instead of relying on printed output.'], ['py-values'], 'A function definition creates reusable behavior; calling it executes the body with arguments bound to parameters. return sends a value back to the caller and ends that invocation. print writes for a human to observe but does not supply a result to the calling expression. Small functions with clear contracts are easier to test and compose.', [('parameter','A parameter is a local name listed in a function definition.'),('argument','An argument is a value supplied by the caller during a function call.'),('return','return ends the current function call and provides its result to the caller.'),('print','print displays text but its return value is None.')]),
('web-html','HTML Structure and Semantic Elements','web-core',35,'Describe page structure and meaning with semantic HTML.', ['Build a valid document skeleton.','Choose elements according to content meaning, not visual appearance.'], [], 'HTML represents document structure and meaning. A document has a doctype, html root, head metadata, and body content. Semantic elements such as main, nav, article, and button communicate purpose to browsers and assistive technology. Use headings in a logical hierarchy; choose an element for its semantics, then style its appearance with CSS.', [('doctype','The HTML doctype tells browsers to use standards mode.'),('head-body','head holds document metadata while body holds page content.'),('semantic','A semantic element expresses the role of its content, such as navigation or main content.'),('button','A button element provides native keyboard and activation behavior for an action.')]),
('web-css-box','CSS Selectors and the Box Model','web-core',35,'Target elements with selectors and reason about their rendered dimensions.', ['Read common selector forms.','Calculate content, padding, border, and margin contributions.'], ['web-html'], 'CSS rules pair a selector with declarations. The cascade resolves competing declarations using origin, importance, specificity, and source order. In the default content-box model, declared width applies to the content box; padding and border add to its outer size. border-box includes padding and border within the declared width, which often simplifies layout.', [('selector','A selector matches the elements to which a CSS rule applies.'),('specificity','Specificity helps decide between competing declarations after cascade origin and importance.'),('content-box','With content-box, declared width excludes padding and border.'),('border-box','With border-box, declared width includes content and padding and border.')]),
('web-dom-events','DOM Events and Browser Interaction','web-core',40,'Respond to user actions through browser events and the document object model.', ['Register event listeners.','Use event targets and prevent default behavior only when appropriate.'], ['web-html'], 'The DOM exposes a document as objects that scripts can inspect and update. Event listeners connect user or browser actions to callbacks. The event target identifies the object on which the event occurred; currentTarget identifies the object whose listener is running. Preventing default behavior should be deliberate—for example, intercepting a validated form submission—not a blanket step.', [('dom','The DOM is a structured object representation of a document.'),('listener','An event listener is a callback invoked when its registered event occurs.'),('target','event.target is the originating event target, which may be a nested element.'),('prevent-default','preventDefault cancels a browser default action when the event is cancelable.')]),
('sql-select','SELECT, WHERE, ORDER BY, and LIMIT','data-core',35,'Retrieve rows, filter them, sort results, and limit output.', ['Write a basic SELECT query.','Explain filtering, ordering, and result limits.'], [], 'A SELECT query describes columns to retrieve and a source table. WHERE filters rows according to a predicate; ORDER BY sorts the remaining result and LIMIT caps how many rows are returned. Without ORDER BY, row order is not guaranteed. SQL uses three-valued logic around NULL, so equality checks with NULL require IS NULL rather than = NULL.', [('select','SELECT names the output expressions or columns.'),('where','WHERE filters input rows before they appear in the result.'),('order-by','ORDER BY explicitly requests a result ordering.'),('limit','LIMIT caps the number of returned rows but does not define which rows without ordering.')]),
('sql-keys','Tables, Primary Keys, and Foreign Keys','data-core',35,'Model entities and preserve relationships with relational constraints.', ['Explain primary-key uniqueness and non-nullability.','Use foreign keys to represent references between tables.'], ['sql-select'], 'A relational table stores rows with a consistent set of columns. A primary key identifies each row uniquely and cannot be NULL. A foreign key constrains a value to reference a key in another table, helping preserve referential integrity. Choose keys that remain stable; a display name is usually a poor key because names can change or collide.', [('primary-key','A primary key uniquely identifies each row and is not NULL.'),('foreign-key','A foreign key references a key in another table and constrains relationship values.'),('referential-integrity','Referential integrity prevents references to nonexistent parent rows.'),('surrogate-key','A surrogate key is an artificial stable identifier with no domain meaning.')]),
('sql-joins','JOIN Operations','data-core',40,'Combine related rows from multiple tables using join conditions.', ['Distinguish inner and left joins.','Predict how join keys affect row counts.'], ['sql-keys'], 'A join combines rows according to a condition. An INNER JOIN returns matching pairs; a LEFT JOIN keeps every left-side row and fills right-side columns with NULL when there is no match. A one-to-many relationship can produce multiple result rows for one left row. Always specify the join condition and inspect key cardinality to avoid accidental row multiplication.', [('inner-join','INNER JOIN retains row pairs for which the join condition matches.'),('left-join','LEFT JOIN preserves every left row, using NULLs for unmatched right columns.'),('join-condition','The ON expression states how rows from the joined tables correspond.'),('cardinality','A one-to-many match can yield multiple output rows for a single left row.')]),
('cs-arrays-lists','Arrays and Dynamic Lists','cs-core',35,'Compare indexed sequences and understand the cost of common operations.', ['Use indexes and trace insertion/removal effects.','Distinguish access complexity from insertion complexity.'], [], 'An array stores elements in indexed positions, often contiguously, enabling constant-time access by index in the standard random-access model. Inserting near the front may require shifting later elements. Dynamic arrays reserve extra capacity and occasionally allocate a larger block; append is amortized O(1), although an individual resize can cost O(n).', [('random-access','An array index can locate an element in O(1) time under the usual model.'),('shift','Inserting at the front of an array may move many existing elements.'),('dynamic-array','A dynamic array grows its capacity when the current storage is full.'),('amortized','Amortized O(1) append means the average cost across a sequence of appends is constant.')]),
('cs-big-o','Algorithmic Complexity and Big-O','cs-core',40,'Describe how resource use scales as input size grows.', ['Compare common growth rates.','Identify the dominant term in a simple complexity expression.'], ['cs-arrays-lists'], 'Big-O describes an asymptotic upper-bound growth class, abstracting away constants and lower-order terms. It helps compare how an algorithm may scale as input size increases, not predict exact wall-clock time. Nested loops do not always imply quadratic work; inspect how many total iterations occur and whether loop bounds depend on input size.', [('asymptotic','Asymptotic analysis studies behavior as input size grows.'),('drop-constants','O(3n) and O(n) belong to the same Big-O growth class.'),('nested-loops','Nested loops are O(n²) only when both perform O(n) iterations for each input.'),('space-complexity','Space complexity describes how auxiliary storage grows with input size.')]),
('cs-bfs','Breadth-First Search','cs-core',40,'Explore a graph in layers and find shortest paths by edge count in unweighted graphs.', ['Trace queue-based traversal.','Explain the conditions for shortest-path guarantees.'], ['cs-arrays-lists'], 'Breadth-first search marks a start vertex and explores its neighbors before vertices farther away. A FIFO queue preserves this layer order. In an unweighted graph, the first discovery of a vertex gives a path with the fewest edges. Mark vertices when enqueuing to avoid adding duplicates; for weighted graphs, ordinary BFS does not generally minimize total weight.', [('fifo','A FIFO queue removes items in the order they were added.'),('layers','BFS explores vertices in nondecreasing number of edges from the start.'),('unweighted-shortest','BFS finds fewest-edge paths when every edge has equal cost.'),('visited','Marking vertices when enqueued prevents repeated queue insertion.')]),
('git-staging','Git Working Tree, Staging, and Commits','git-core',30,'Select project changes and record them as durable snapshots.', ['Distinguish working tree, index, and commit.','Stage only the intended changes before committing.'], [], 'Git separates the working tree (files you edit), the index (the proposed next snapshot), and commits (saved snapshots). git add copies selected content into the index; it does not create a commit. A commit records the index with metadata and a parent relationship. Reviewing git diff and git status before committing catches accidental or incomplete staging.', [('working-tree','The working tree is the checked-out files currently being edited.'),('index','The index, or staging area, describes the content for the next commit.'),('git-add','git add stages selected changes in the index.'),('commit','A commit records a snapshot of staged content and points to its parent commit.')]),
('git-branches','Branches and Merging','git-core',35,'Develop changes on independent lines and integrate compatible histories.', ['Explain a branch as a movable reference.','Recognize fast-forward and three-way merge outcomes.'], ['git-staging'], 'A Git branch is a lightweight movable reference to a commit, not a separate copy of every file. Switching branches changes the checked-out snapshot. A fast-forward moves the target reference when it has no divergent work; otherwise Git combines histories with a merge commit or reports conflicts that need resolution. Commit or safely save local work before switching.', [('branch-ref','A branch is a named reference that normally advances when new commits are made on it.'),('fast-forward','A fast-forward is possible when the target branch is an ancestor of the branch being integrated.'),('merge-commit','A merge commit records two parent histories after divergent branches are combined.'),('conflict','A merge conflict means Git cannot automatically choose how overlapping changes should combine.')]),
('git-remotes','Remote Repositories and Synchronization','git-core',35,'Exchange commits with remote repositories while keeping local history understandable.', ['Distinguish fetch, pull, and push.','Check remote-tracking state before synchronization.'], ['git-branches'], 'A remote is a named reference to another repository location. fetch downloads objects and updates remote-tracking references without merging into the current branch. pull fetches and then integrates according to configuration (commonly merge or rebase). push sends local commits to a remote, subject to permissions and history rules. Inspect status and the target branch before synchronization.', [('remote','A remote names another repository and its fetch/push configuration.'),('fetch','git fetch downloads updates without integrating them into the current branch.'),('pull','git pull fetches and then integrates remote changes.'),('push','git push publishes local commits to a remote branch when allowed.')]),
]

def build_library():
    modules = [dict(item) for item in MODULES]
    topics = []
    row_map = {row[0]: row for row in _ROWS}
    # Facts are authored topic-specific checks; neighboring facts serve as plausible contrasts.
    for row in _ROWS:
        slug, title, module, minutes, summary, objectives, prereqs, explanation, facts = row
        neighbors = [fact[1] for other in _ROWS if other[0] != slug for fact in other[-1]]
        questions = []
        for i, (term, correct_statement) in enumerate(facts):
            distractors = [f[1] for f in facts if f[0] != term][:3]
            while len(distractors) < 3:
                distractors.append(neighbors[(i + len(distractors)) % len(neighbors)])
            choices = [correct_statement] + distractors
            # Deterministic ordering and answer key avoid positional answer bias.
            correct_index = (i * 3 + 1) % 4
            ordered = choices[1:]
            ordered.insert(correct_index, choices[0])
            objective = objectives[min(i % len(objectives), len(objectives)-1)]
            for variant, prompt, kind in [
                (0, f'Which statement about {term.replace("-", " ")} is accurate?', 'concept_check'),
                (1, f'A learner is applying {term.replace("-", " ")} to a new example. Which rule should guide the decision?', 'application'),
            ]:
                questions.append({'prompt':prompt, 'choices':ordered, 'correct':correct_index, 'difficulty':round(.2 + .08 * ((i + variant) % 5), 2), 'type':kind, 'explanation':correct_statement + (' This matters because it guides correct prediction and implementation.' if not variant else ' Apply this rule to the example, then check that each condition in the rule is satisfied.'), 'learning_objective':objective, 'distractor_explanations':[{'choice':d,'feedback':'This describes a different concept or reverses the rule; compare it with the stated learning objective.'} for j,d in enumerate(ordered) if j != correct_index]})
        topics.append({'slug':slug,'title':title,'module_id':module,'minutes':minutes,'summary':summary,'objectives':objectives,'prerequisites':prereqs,'explanation':explanation,'terminology':[{'term':term.replace('-', ' '),'definition':definition} for term,definition in facts],'worked_examples':[{'title':'Reason through a small case','steps':[facts[0][1],facts[1][1],facts[2][1]],'takeaway':facts[3][1]}], 'exercises':[{'prompt':f'Explain in your own words: {facts[i][1]}','success_criteria':'State the key rule and demonstrate it with a small example.'} for i in range(2)], 'misconceptions':[{'claim':f'Common misconception: {facts[i][1]}','correction':f'Use this precise rule instead: {facts[(i+1)%4][1]}'} for i in range(2)],'mastery_criteria':['Explain the key terms without relying on memorized wording.','Apply the rules to a new example and justify the result.','Identify and correct a representative misconception.'],'questions':questions,'review_status':'approved','provenance':'ORBIT original authored learning content'})
    return extend_library({'tracks':[dict(item) for item in TRACKS], 'modules':modules, 'topics':topics})
